if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_arch() {
    _helper_xcodebuild_show_settings |
        sed -n 's/^[[:space:]]*ARCHS = //p' |
        tr ' ' '\n' |
        sed '/^$/d'
}

_choice_buildaction() {
    cat <<-'EOF'
	analyze	analyze the project
	archive	archive the scheme
	build	build the scheme or target
	build-for-testing	build without running tests
	clean	remove build products
	docbuild	build documentation
	install	install the built products
	installhdrs	install headers
	installsrc	install source
	test	build and run tests
	test-without-building	run tests without building
	EOF
}

_choice_buildsetting() {
    _argc_util_mode_kv =
    [[ -n "$argc__kv_prefix" ]] && return 0
    _choice_buildaction
    _helper_xcodebuild_show_settings |
        sed -n 's/^[[:space:]]*\([A-Za-z_][A-Za-z0-9_]*\) = .*/\1/p' |
        _argc_util_transform suffix== nospace
}

_choice_configuration() {
    _helper_xcodebuild_list '.project.configurations[]?'
}

_choice_destination() {
    local -a args=(-showdestinations)
    [[ -n "${argc_project:-}" ]] && args+=(-project "$argc_project")
    [[ -n "${argc_workspace:-}" ]] && args+=(-workspace "$argc_workspace")
    [[ -n "${argc_scheme:-}" ]] && args+=(-scheme "$argc_scheme")
    xcodebuild "${args[@]}" 2>/dev/null |
        gawk '
        /^[[:space:]]*\{/ {
            line = $0
            sub(/^[^{]*\{[[:space:]]*/, "", line)
            sub(/\}[[:space:]]*$/, "", line)
            count = split(line, parts, /,[[:space:]]*/)
            for (i = 1; i <= count; i++) {
                if (parts[i] !~ /^[A-Za-z]+:/) continue
                key = parts[i]
                sub(/:.*/, "", key)
                value = parts[i]
                sub(/^[^:]+:[[:space:]]*/, "", value)
                if (key ~ /^(platform|name|id|OS|arch|variant)$/) print key "=" value
            }
        }' |
        _argc_util_comp_multi ,
}

_choice_project() {
    find . -maxdepth 3 -name '*.xcodeproj' -print 2>/dev/null |
        sed 's|^\./||' |
        _argc_util_comp_parts /
}

_choice_scheme() {
    _helper_xcodebuild_list '.workspace.schemes[]?, .project.schemes[]?'
}

_choice_sdk() {
    xcodebuild -showsdks 2>/dev/null |
        sed -nE 's/.*[[:space:]]-sdk[[:space:]]+([^[:space:]]+).*/\1/p'
}

_choice_target() {
    _helper_xcodebuild_list '.project.targets[]?'
}

_choice_testplan() {
    local -a args=(-showTestPlans)
    [[ -n "${argc_project:-}" ]] && args+=(-project "$argc_project")
    [[ -n "${argc_workspace:-}" ]] && args+=(-workspace "$argc_workspace")
    [[ -n "${argc_scheme:-}" ]] && args+=(-scheme "$argc_scheme")
    xcodebuild "${args[@]}" 2>/dev/null |
        sed -n '/[Tt]est [Pp]lans/,$p' |
        sed -n 's/^[[:space:]][[:space:]]*\([^[:space:]].*\)$/\1/p'
}

_choice_workspace() {
    find . -maxdepth 3 -name '*.xcworkspace' -print 2>/dev/null |
        sed 's|^\./||' |
        _argc_util_comp_parts /
}

_helper_xcodebuild_list() {
    local -a args=(-list -json)
    [[ -n "${argc_project:-}" ]] && args+=(-project "$argc_project")
    [[ -n "${argc_workspace:-}" ]] && args+=(-workspace "$argc_workspace")
    xcodebuild "${args[@]}" 2>/dev/null | jq -b -r "$1"
}

_helper_xcodebuild_show_settings() {
    local -a args=(-showBuildSettings)
    [[ -n "${argc_project:-}" ]] && args+=(-project "$argc_project")
    [[ -n "${argc_workspace:-}" ]] && args+=(-workspace "$argc_workspace")
    [[ -n "${argc_scheme:-}" ]] && args+=(-scheme "$argc_scheme")
    xcodebuild "${args[@]}" 2>/dev/null
}
